// float's members: one function per member, each declared by the //kavun:member directive in its doc comment. The
// table, floatMethods, and the member entries of docs/reference/types/float.md (alphabetical, so the order here is
// free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Report truthiness, which is inequality with zero: `!!x` ⟺ `x != 0.0`; NaN raises (see [Truthiness](#truthiness)).
//
//kavun:member is_true pure () -> bool
func floatIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// Verbs `f` / `F` (fixed-point, default precision 6), `e` / `E` (scientific), `g` / `G` (shortest, the default),
// `%` (×100 with a percent sign); precision, grouping, sign, and zero-padding compose. NaN/Inf render as text:
//
// ```go
// (1234.5678).format(".2f")     // => "1234.57"
// (1234.5678).format(",.2f")    // => "1,234.57"
// (0.1234).format(".1%")        // => "12.3%"
// (12345.678).format("e")       // => "1.234568e+04"
// (1.5).format("+.1f")          // => "+1.5"
// float("nan").format("f")      // => "NaN"
// float("inf").format("f")      // => "Inf"
// ```
//
//kavun:member format pure ([spec]) -> string
func floatFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Answer the receiver — a `float` is always immutable.
//
// Identity no-ops (a `float` is always immutable), kept for generic code: `(1.5).copy()` → `1.5`.
//
//kavun:member copy pure () -> float
func floatCopy(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver — a `float` is always immutable; see [`copy`](#copy).
//
//kavun:member freeze pure () -> float
func floatFreeze(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver, the identity conversion.
//
//kavun:member float pure ([default]) -> float
func floatFloat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), floatTypeName, args, true, v)
}

// Convert to a `decimal` through the shortest decimal reading; NaN and ±Inf raise unless a default is given.
//
// ```go
// (1.5).decimal()           // => 1.5d
// float("inf").decimal()    // Error: conversion: cannot convert float to decimal
// ```
//
//kavun:member decimal pure ([default]) -> decimal
func floatDecimal(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	f := math.Float64frombits(v.Data)
	// a NaN decimal is an error state, never a produced value: NaN/Inf decline, and so does a finite float
	// too large for dec128's 128-bit coefficient — FromFloat64 signals that overflow as NaN too
	ok := !math.IsInf(f, 0) && !math.IsNaN(f)
	var d Value
	if ok {
		dd := dec128.FromFloat64(f)
		if ok = !dd.IsNaN(); ok {
			d = NewDecimalValue(dd)
		}
	}
	return ConvMember(id.String(), floatTypeName, args, ok, d)
}

// Truncate toward zero to an `int`; NaN, ±Inf and out-of-range values raise unless a default is given.
//
// ```go
// (1.9).int()               // => 1 — truncation toward zero
// (-1.9).int()              // => -1
// float("nan").int()        // Error: conversion: cannot convert float to int
// float("nan").int(0)       // => 0
// (1e300).int()             // Error: conversion: cannot convert float to int — out of range
// ```
//
//kavun:member int pure ([default]) -> int
func floatInt(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	i, ok := v.AsInt()
	return ConvMember(id.String(), floatTypeName, args, ok, IntValue(i))
}

// Answer `false` for zero and `true` otherwise; NaN raises unless a default is given.
//
// ```go
// (0.5).bool()              // => true
// ```
//
//kavun:member bool pure ([default]) -> bool
func floatBool(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	b, ok := v.AsBool()
	return ConvMember(id.String(), floatTypeName, args, ok, BoolValue(b))
}

// Read the value as a unix timestamp in seconds, the fraction included.
//
// A float in conversion context is a unix timestamp read as `seconds.fraction` — and float64 precision only reaches
// about a microsecond for present-day timestamps:
//
// ```go
// (0.5).time()             // => time("1970-01-01T00:00:00.5Z")
// (1704067200.123).time()  // => time("2024-01-01T00:00:00.122999907Z") — float rounding, not a bug
// ```
//
// Use `decimal` (exact to the nanosecond) or `int` `.time_nano()` when the sub-second part must be right.
//
//kavun:member time pure ([default]) -> time
func floatTime(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	t, ok := v.AsTime()
	return ConvMember(id.String(), floatTypeName, args, ok, NewTimeValue(t))
}

// Render the value as its shortest round-trip text, a `string`.
//
// ```go
// (1.5).string()            // => "1.5"
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member string pure ([default]) -> string
func floatString(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	s, _ := v.AsString()
	return ConvMember(id.String(), floatTypeName, args, true, NewStringValue(s))
}

// Render the value as its shortest round-trip text, as `runes`; see [`string`](#string).
//
// ```go
// (1.5).runes()             // => u"1.5"
// ```
//
//kavun:member runes pure ([default]) -> runes
func floatRunes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	s, ok := v.AsString()
	return ConvMember(id.String(), floatTypeName, args, ok, NewRunesValue(text.DecodeText(s), false))
}

// Report whether the value is NaN.
//
// `is_nan()` / `is_inf()` are the safe way to interrogate a value that arithmetic would refuse; every numeric type
// answers them (constantly `false` on `int` and for `is_inf` on `decimal`), so generic code never type-switches.
//
//kavun:member is_nan pure () -> bool
func floatIsNaN(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return BoolValue(math.IsNaN(math.Float64frombits(v.Data))), nil
}

// Report whether the value is infinite; see [`is_nan`](#is_nan).
//
//kavun:member is_inf pure () -> bool
func floatIsInf(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	// no sign argument: -Inf is x.is_inf() && x.sign() < 0
	return BoolValue(math.IsInf(math.Float64frombits(v.Data), 0)), nil
}

// Report whether the value is zero.
//
// ```go
// (0.0).is_zero()         // => true
// ```
//
// Negative zero compares equal to zero and reads as zero everywhere:
//
// ```go
// (-0.0).is_zero()        // => true
// (-0.0).is_negative()    // => false
// (-0.0).sign()           // => 0
// ```
//
//kavun:member is_zero pure () -> bool
func floatIsZero(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return BoolValue(math.Float64frombits(v.Data) == 0), nil
}

// Report whether the value is less than zero.
//
// ```go
// (-2.5).is_negative()    // => true
// ```
//
//kavun:member is_negative pure () -> bool
func floatIsNegative(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return BoolValue(math.Float64frombits(v.Data) < 0), nil
}

// Report whether the value is greater than zero.
//
// ```go
// (2.5).is_positive()     // => true
// ```
//
//kavun:member is_positive pure () -> bool
func floatIsPositive(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return BoolValue(math.Float64frombits(v.Data) > 0), nil
}

// Answer the absolute value.
//
// ```go
// (-2.5).abs()            // => 2.5
// ```
//
//kavun:member abs pure () -> float
func floatAbs(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FloatValue(math.Abs(math.Float64frombits(v.Data))), nil
}

// Answer the sign as an `int`: `-1`, `0` or `1`.
//
// ```go
// (-2.5).sign()           // => -1
// (0.0).sign()            // => 0
// float("nan").sign()     // => 0
// ```
//
//kavun:member sign pure () -> int
func floatSign(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	f := math.Float64frombits(v.Data)
	if math.IsNaN(f) {
		return IntValue(0), nil
	}
	if f > 0 {
		return IntValue(1), nil
	}
	if f < 0 {
		return IntValue(-1), nil
	}
	return IntValue(0), nil
}

// --- numeric members: the readings decimal has, on a float, in table order. No member may produce NaN or ±Inf
// (floatResult), exactly as no float operator may. The rounding members apply decimal's contract — its seven modes,
// through the shared roundingMode — to the float's shortest decimal text, the digits string() prints, so
// 2.675.round(2, "half_up") is 2.68. They round the text itself (floatRoundKeep), so no magnitude is out of range.

// Clamp the value into `[lo, hi]`.
//
// ```go
// 5.0.clamp(0, 2)           // => 2.0 — clamp(lo, hi) needs lo <= hi
// ```
//
//kavun:member clamp pure (lo, hi) -> float
func floatClamp(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	lo, err := floatOperandArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	hi, err := floatOperandArg(name, "second", args[1])
	if err != nil {
		return Undefined, err
	}
	if lo > hi {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) lower bound %s is above upper bound %s", name, FloatValue(lo).String(), FloatValue(hi).String()))
	}
	return floatResult(name, math.Min(math.Max(math.Float64frombits(v.Data), lo), hi))
}

// Answer the square root.
//
// ```go
// 16.0.sqrt()               // => 4.0
// (-1.0).sqrt()             // Error: invalid_value: (sqrt) the result is not a number
// ```
//
//kavun:member sqrt pure () -> float
func floatSqrt(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	return floatResult(name, math.Sqrt(math.Float64frombits(v.Data)))
}

// Raise the value to `exponent`.
//
// ```go
// 2.0.pow(10)               // => 1024.0 — the exponent may be an int or a float
// 2.0.pow(0.5)              // => 1.4142135623730951
// 0.0.pow(-1)               // Error: division_by_zero: division by zero
// ```
//
//kavun:member pow pure (exponent) -> float
func floatPow(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	x := math.Float64frombits(v.Data)
	y, err := floatOperandArg(name, "exponent", args[0])
	if err != nil {
		return Undefined, err
	}
	if x == 0 && y < 0 { // the reciprocal of zero, reported as decimal reports it
		return Undefined, errs.NewDivisionByZeroError()
	}
	return floatResult(name, math.Pow(x, y))
}

// Answer the magnitude of the receiver with the sign of `y`.
//
// ```go
// 1.5.copy_sign(-2)         // => -1.5
// ```
//
//kavun:member copy_sign pure (y) -> float
func floatCopySign(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	sign, err := floatOperandArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	return floatResult(name, math.Copysign(math.Float64frombits(v.Data), sign))
}

// Round to `n` fractional places with the rounding `mode`.
//
// `round(n, mode)` and its fixed-mode twins `round_half_even(n)`, `round_half_up`, `round_half_down`,
// `round_up`, `round_down`, `round_ceiling`, `round_floor`, plus `round_to_multiple(m, mode)` and
// `round_significant(k, mode)`, are **decimal's contract**: `n` is required (negative rounds to tens,
// hundreds, …), and `mode` is one of `half_even`, `half_up`, `half_down`, `up`, `down`, `ceiling`, `floor`.
//
// A float rounds **the digits it prints** — its shortest decimal text, the one `string()` shows — not its exact
// binary value. So rounding does what the reader expects from the number they see:
//
// ```go
// 2.675.round(2, "half_up")          // => 2.68 — 2.675 is stored as 2.67499999…; it prints, and rounds, as 2.675
// (0.1 + 0.2).round(1, "half_even")  // => 0.3
// 1234.5.round(-2, "half_up")        // => 1200.0
// 3.7.round_floor(0)                 // => 3.0 — floor / ceil / trunc are round_floor / round_ceiling / round_down at 0
// 1.234.round_to_multiple(0.05, "half_up")    // => 1.25
// 123456.0.round_significant(2, "half_even")  // => 120000.0
// 1.5.round(2, "bankers")            // Error: invalid_value: unknown rounding mode "bankers", expected one of: ceiling, …
// ```
//
// Float rounds those digits itself, with the same seven modes as `decimal` (and, wherever `decimal` can hold the value,
// exactly the same answer), so no magnitude is out of range: `1e-30.round(2, "half_up")` is `0.0`, and
// `1e300.round(2, "half_up")` is `1e300` unchanged. Only a result past float's own range raises
// (`1.7976931348623157e308.round(-308, "up")` would be `2e308`); NaN and ±Inf have no digits to round and raise too.
//
//kavun:member round pure (n, mode) -> float
func floatRound(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	places, err := floatPlacesArg(name, "places", args[0])
	if err != nil {
		return Undefined, err
	}
	mode, err := roundingModeArg(name, "mode", args[1])
	if err != nil {
		return Undefined, err
	}
	return floatRoundPlaces(name, v, places, mode)
}

